import type { OrderWithCustomer } from '../db/types';

const HEADER = ['order_id', 'date', 'customer_name', 'email', 'total', 'status'];

export function ordersToCsv(orders: OrderWithCustomer[]): string {
  const rows = orders.map(o => [o.id, o.createdAt.toLocaleDateString(), o.customer.name, o.customer.email, o.total.toFixed(2), o.status].join(','));
  return [HEADER.join(','), ...rows].join('\n');
}

import { listOrders } from '@/lib/db/orders';
import { ordersToCsv } from '@/lib/export/ordersCsv';

export async function GET(req: Request) {
  const url = new URL(req.url);
  const from = url.searchParams.get('from');
  const to = url.searchParams.get('to');
  const orders = await listOrders({ from: from ? new Date(from) : undefined, to: to ? new Date(to) : undefined });
  return new Response(ordersToCsv(orders), { headers: { 'Content-Type': 'text/csv', 'Content-Disposition': 'attachment; filename=orders.csv' } });
}
